{"sql": "SELECT m.chembl_id AS compound_chembl_id, cr.compound_key, COALESCE(d.pubmed_id, d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary parent JOIN molecule_hierarchy mh ON mh.parent_molregno = parent.molregno JOIN molecule_dictionary m ON m.molregno = mh.molregno JOIN compound_records cr ON cr.molregno = m.molregno JOIN docs d ON d.doc_id = cr.doc_id JOIN activities act ON act.record_id = cr.record_id JOIN assays a ON a.assay_id = act.assay_id JOIN target_dictionary td ON td.tid = a.tid WHERE parent.chembl_id = 'CHEMBL941' AND act.standard_type = 'IC50' AND act.standard_units = 'nM' AND td.chembl_id = 'CHEMBL1936' ORDER BY m.chembl_id, cr.compound_key, COALESCE(d.pubmed_id, d.doi), a.description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, td.chembl_id, td.pref_name, td.organism"}
